type WorkflowState =
  | "intake" | "planning" | "authorization" | "execution"
  | "verification" | "reconciliation" | "completed" | "failed";

interface StateTransition {
  from: WorkflowState;
  to: WorkflowState;
  evidence: string; // the durable record that proves the transition occurred
}

function assertKnownTransition(t: StateTransition, allowed: Set<string>) {
  const key = `${t.from}->${t.to}`;
  if (!allowed.has(key)) throw new Error(`Unmodeled transition: ${key}`);
}

interface ToolPermission {
  toolName: string;
  allowedOperation: string;
  deniedOperations: string[];
  approvalRequired: boolean;
  executionLimit: number;
}

const permissions: ToolPermission[] = [
  { toolName: "read_case", allowedOperation: "read", deniedOperations: ["write", "delete"], approvalRequired: false, executionLimit: 50 },
  { toolName: "send_reply", allowedOperation: "create-draft", deniedOperations: ["send-without-approval"], approvalRequired: true, executionLimit: 1 },
];

interface HandoffPacket {
  objective: string;
  constraints: string[];
  authoritativeEvidence: string[];
  currentState: WorkflowState;
  outputSchema: string;
  escalationRule: string;
}

function acceptHandoff(packet: HandoffPacket): { accepted: boolean; reason?: string } {
  if (!packet.authoritativeEvidence.length) return { accepted: false, reason: "missing evidence" };
  if (!packet.escalationRule) return { accepted: false, reason: "missing escalation rule" };
  return { accepted: true };
}

interface FailureTest {
  id: string;
  inject: "tool-denial" | "malformed-output" | "timeout" | "partial-write" | "duplicate-request";
  expectedContainment: string;
}

async function runFailureTest(test: FailureTest): Promise<{ passed: boolean; observed: string }> {
  const observed = await simulateFailure(test.inject);
  return { passed: observed === test.expectedContainment, observed };
}

