interface CriterionEvidence {
  criterionId: string;
  pointsAwarded: number;
  evidenceRefs: string[];
}

function validateEvidenceMap(scores: CriterionEvidence[]): string[] {
  return scores.filter((s) => s.evidenceRefs.length === 0).map((s) => s.criterionId);
}

